  "hypothesis": "Replacing the five fixed mixture weights with an active-peak, continuous line search will find improving packet-remeshing mixtures that the coarse schedule misses.",
  "rationale": "The incumbent is near a nonsmooth maximum, so useful mixture weights may lie between the tested values or far below the smallest one. Along each remeshing direction the convolution is quadratic and its squared norm is quartic, allowing inexpensive optimization against an adaptively expanded set of peak constraints, followed by exact verification.",
  "source": "import time
import numpy as np
from scipy.fft import rfft, irfft, next_fast_len
from scipy.signal import oaconvolve
from scipy.optimize import minimize_scalar

PARAMS = {
    'proposals': (24, 6, 64),
    'width_step': (1.0, 0.25, 8.0),
    'reserve': (0.70, 0.5, 0.75)
}

def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + float(params['reserve']) * budget_s
    rng = np.random.default_rng(seed)
    def alive(margin=0.0):
        return time.monotonic() + margin < deadline
    def exact(f):
        c = oaconvolve(np.maximum(f, 0.0), np.maximum(f, 0.0), mode='full')
        m = len(c)
        dx = np.diff(np.linspace(-0.5, 0.5, m + 2))
        y = np.concatenate(([0.0], c, [0.0]))
        numerator = float(np.sum((dx / 3.0) * (y[:-1]**2 + y[:-1]*y[1:] + y[1:]**2)))
        return numerator / ((np.sum(np.abs(c))/(m+1))*np.max(np.abs(c)))
    if init is None:
        return {'length': 1, 'packets': [[0, [1.0]]]}
    if 'values' in init:
        raw = init['values']
    else:
        raw = np.zeros(int(init['length']))
        for a, v in init['packets']:
            if not alive(4):
                return init
            raw[int(a):int(a)+len(v)] += np.asarray(v)
    f = np.maximum(np.asarray(raw, dtype=np.float64), 0.0)
    baseline = exact(f)
    if not alive(5) or len(f) < 4:
        return init
    n = len(f)
    f = f / np.max(f)
    edges = np.diff(np.r_[False, f > 0, False].astype(np.int8))
    aa = np.flatnonzero(edges == 1)
    bb = np.flatnonzero(edges == -1)
    if len(aa) < 2:
        return init
    mass = np.r_[0.0, np.cumsum(f)]
    heavy = int(np.argmax(mass[bb]-mass[aa]))
    prefixes = []
    for a,b in zip(aa,bb):
        if not alive(5):
            return init
        prefixes.append(np.r_[0.0, np.cumsum(f[a:b])])
    nc = 2*n-1
    L = next_fast_len(nc)
    F = rfft(f,L,workers=1)
    c = irfft(F*F,L,workers=1)[:nc]
    best_score = baseline
    best = None
    step = float(params['width_step'])
    specs = []
    for delta in (step, -step, 2*step, -2*step, 4*step, -4*step):
        if not alive(4):
            break
        for anchor in (0.5, 0.0, 1.0):
            if not alive(4):
                break
            specs.append((delta, anchor, 0))
    specs += [(step,0.5,1),(-step,0.5,1),(2*step,0.5,2),(-2*step,0.5,2),(.20,0.5,3),(-.20,0.5,3)]
    for j in range(max(0,int(params['proposals'])-len(specs))):
        if not alive(5):
            break
        specs.append((float(rng.choice([-1,1]))*step*float(rng.uniform(.5,5)), float(rng.choice([0,.5,1])), int(rng.integers(0,3))))

    def bilinear(a,b):
        return float(2*np.dot(a,b) + .5*(np.dot(a[:-1],b[1:])+np.dot(b[:-1],a[1:])))

    for delta,anchor,mode in specs[:int(params['proposals'])]:
        if not alive(6):
            break
        g = np.zeros(n,dtype=np.float64)
        complete = True
        for j,(a,b) in enumerate(zip(aa,bb)):
            if not alive(5):
                complete = False
                break
            a,b = int(a),int(b)
            w = b-a
            if j == heavy:
                g[a:b] += f[a:b]
                continue
            x = (a+b)/(2.0*n)
            if mode == 1:
                change = delta*(2*x-1)
            elif mode == 2:
                change = delta*np.cos(2*np.pi*x)
            elif mode == 3:
                change = delta*w
            else:
                change = delta
            new_w = max(0.25,w+change)
            left = a-anchor*(new_w-w)
            right = left+new_w
            if left < 0:
                right -= left
                left = 0.0
            if right > n:
                left -= right-n
                right = float(n)
            left = max(0.0,left)
            actual = right-left
            if actual <= 0:
                complete = False
                break
            lo = max(0,int(np.floor(left)))
            hi = min(n,int(np.ceil(right)))
            boundaries = np.arange(lo,hi+1,dtype=np.float64)
            old_coordinate = np.clip((boundaries-left)*(w/actual),0.0,float(w))
            ix = np.minimum(np.floor(old_coordinate).astype(np.int64),w-1)
            integral = prefixes[j][ix] + (old_coordinate-ix)*f[a+ix]
            g[lo:hi] += np.maximum(np.diff(integral),0.0)
        if not complete or not alive(5):
            break
        d = g-f
        D = rfft(d,L,workers=1)
        u = 2*irfft(F*D,L,workers=1)[:nc]
        v = irfft(D*D,L,workers=1)[:nc]
        if not alive(4):
            break
        # The numerator is quartic; only the maximum needs active constraints.
        q = np.array([bilinear(c,c),2*bilinear(c,u),bilinear(u,u)+2*bilinear(c,v),2*bilinear(u,v),bilinear(v,v)])
        sums = np.array([np.sum(c),np.sum(u),np.sum(v)])
        indices = {int(np.argmax(c))}
        probes = [0.0,1e-8,1e-6,1e-4,.003,.03,.125,.5,1.0]
        winner = None
        winner_score = best_score
        for alpha in probes:
            if not alive(3.5):
                break
            cc = c+alpha*u+alpha*alpha*v
            k = int(np.argmax(cc))
            indices.add(k)
            score = float(np.polynomial.polynomial.polyval(alpha,q)/(3*np.sum(np.abs(cc))*np.max(np.abs(cc))))
            if alpha > 0 and score > winner_score + 2e-13:
                winner_score, winner = score, alpha
        # Constraint generation: solve against current peaks, then add the true peak.
        for iteration in range(7):
            if not alive(3.5):
                break
            ids = np.array(sorted(indices),dtype=np.int64)
            ca,ua,va = c[ids],u[ids],v[ids]
            def objective(a):
                if not alive(3):
                    return 1e6
                top = float(np.max(ca+a*ua+a*a*va))
                den = 3*np.polynomial.polynomial.polyval(a,sums)*top
                return -float(np.polynomial.polynomial.polyval(a,q)/den) if den > 0 else 1e6
            # Search on a logarithmic coordinate, retaining all coarse intervals.
            grid = np.array([0.,1e-10,1e-8,1e-6,1e-4,.003,.03,.125,.5,1.])
            vals = []
            for a in grid:
                if not alive(3.2):
                    break
                vals.append(objective(float(a)))
            if len(vals) != len(grid):
                break
            k = int(np.argmin(vals))
            lo = float(grid[max(0,k-1)])
            hi = float(grid[min(len(grid)-1,k+1)])
            result = minimize_scalar(objective,bounds=(lo,hi),method='bounded',options={'xatol':1e-12,'maxiter':65})
            alpha = float(result.x)
            if vals[k] < result.fun:
                alpha = float(grid[k])
            if not alive(3):
                break
            cc = c+alpha*u+alpha*alpha*v
            peak = int(np.argmax(cc))
            score = float((2*np.dot(cc,cc)+np.dot(cc[:-1],cc[1:]))/(3*np.sum(np.abs(cc))*np.max(np.abs(cc))))
            if alpha > 0 and score > winner_score + 2e-13:
                winner_score,winner = score,alpha
            if peak in indices:
                break
            indices.add(peak)
        if winner is not None and alive(2.5):
            proposal = np.maximum(f+winner*d,0.0)
            verified = exact(proposal)
            if verified > best_score:
                best_score = verified
                best = proposal
    if best is None:
        return init
    transitions = np.diff(np.r_[False,best > 0,False].astype(np.int8))
    starts = np.flatnonzero(transitions == 1)
    stops = np.flatnonzero(transitions == -1)
    packets = []
    for a,b in zip(starts,stops):
        if time.monotonic() > start + .90*budget_s:
            return init
        packets.append([int(a),best[a:b].tolist()])
    return {'length': n, 'packets': packets}
